export function createDraftsUI({e,api,ui,link}){
 const counted=(n,singular,plural=singular+'s')=>n+' '+(n===1?singular:plural);
 const date=d=>new Date(d+'T12:00Z').toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'});
 const type={unit:'Unit',quiz:'Quiz',assignment:'Assignment'};
 async function page(params){
  const q=new URLSearchParams();for(const k of ['classId','kind','search','offset'])if(params.get(k))q.set(k,params.get(k));const d=await api('drafts?'+q);
  const paging={view:'drafts'};for(const k of ['classId','kind','search'])if(params.get(k))paging[k]=params.get(k);
  return '<div class="learning-section-title"><h2>Your drafts</h2>'+link('Resume saved marking →',{view:'inbox',status:'drafts'})+'<button type="button" class="btn" data-drafts-refresh>Refresh</button></div><p>Pick up unfinished work across your classes. Draft units and tasks stay hidden from students until you publish them.</p><p>'+counted(d.counts.unit,'unit')+' · '+counted(d.counts.quiz,'quiz','quizzes')+' · '+counted(d.counts.assignment,'assignment')+' across your classes</p><form class="community-filters" id="drafts-filters"><label>Class<select name="classId"><option value="">All my classes</option>'+d.classes.map(c=>'<option value="'+e(c.id)+'" '+(params.get('classId')===c.id?'selected':'')+'>'+e(c.name)+'</option>').join('')+'</select></label><label>Type<select name="kind"><option value="">All drafts</option>'+Object.entries(type).map(([k,t])=>'<option value="'+k+'" '+(params.get('kind')===k?'selected':'')+'>'+t+'</option>').join('')+'</select></label><label>Find<input name="search" maxlength="120" placeholder="Title, subject or unit" value="'+e(params.get('search')||'')+'"></label><button class="btn" type="submit">Find drafts</button>'+link('Clear filters',{view:'drafts'})+'</form><div class="learning-section-title"><strong>'+counted(d.total,'matching draft')+'</strong><span>'+(d.total?(d.offset+1)+'–'+Math.min(d.total,d.offset+d.limit)+' of '+d.total:'')+'</span></div><section class="vle-panel table-wrap"><table class="data-table drafts-table"><thead><tr><th scope="col">Draft / class</th><th scope="col">Details</th><th scope="col">Continue</th></tr></thead><tbody>'+d.items.map(r=>'<tr><td><strong>'+e(r.title)+'</strong><small>'+e(r.className)+' · '+type[r.kind]+'</small></td><td>'+(r.kind==='unit'?counted(r.taskCount,'task')+' · '+r.selectedCount+' selected'+(r.planSaved?'<small>Draft plan saved</small>':'<small>Ready to plan</small>'):(r.due?'Due '+e(date(r.due)):'No deadline')+' · '+counted(r.maximum,'point')+(r.unitTitle?'<small>Unit: '+e(r.unitTitle)+(r.unitDraft?' · Private draft':'')+'</small>':''))+'</td><td>'+(r.kind==='unit'?link('Review & publish',{publishUnit:r.id})+'<br>'+link('Edit material',{class:r.classId,tab:'units',unit:r.id}):link(r.kind==='quiz'?'Continue quiz':'Continue assignment',r.kind==='quiz'?{class:r.classId,quizEditor:r.id}:{class:r.classId,assignment:r.id})+(r.unitDraft?'<br>'+link('Review unit plan',{publishUnit:r.unitId}):''))+'</td></tr>').join('')+'</tbody></table>'+(!d.items.length?'<p class="learning-empty">'+(q.size?'No drafts match these filters. Try another class or clear the filters.':'No unfinished work here. Open a classroom to create a unit, assignment or quiz.')+'</p>':'')+'</section><div class="vle-actions">'+(d.offset?link('← Previous',{...paging,offset:Math.max(0,d.offset-d.limit)}):'')+(d.offset+d.limit<d.total?link('Next →',{...paging,offset:d.offset+d.limit}):'')+'</div>';
 }
 function bind(root){root.querySelector('[data-drafts-refresh]')?.addEventListener('click',()=>ui.render());root.querySelector('#drafts-filters')?.addEventListener('submit',ev=>{ev.preventDefault();const q=new URLSearchParams({view:'drafts'});for(const [k,v]of new FormData(ev.currentTarget))if(v)q.set(k,v);const target='#/classroom?'+q;if(location.hash===target)ui.render();else location.hash=target;});}
 return{page,bind};
}


